create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default 'Пользователь', phone text unique, avatar_url text, created_at timestamptz not null default now());
create table if not exists public.chats (id uuid primary key default gen_random_uuid(), is_group boolean not null default false, title text, created_by uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.chat_members (chat_id uuid not null references public.chats(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null default 'member' check (role in ('owner','admin','member')), joined_at timestamptz not null default now(), primary key(chat_id,user_id));
create table if not exists public.messages (id uuid primary key default gen_random_uuid(), chat_id uuid not null references public.chats(id) on delete cascade, sender_id uuid not null references auth.users(id) on delete cascade, body text not null check (char_length(body) between 1 and 10000), created_at timestamptz not null default now(), edited_at timestamptz, deleted_at timestamptz);
create index if not exists messages_chat_created_idx on public.messages(chat_id,created_at desc);
create index if not exists chat_members_user_idx on public.chat_members(user_id);
alter table public.profiles enable row level security; alter table public.chats enable row level security; alter table public.chat_members enable row level security; alter table public.messages enable row level security;
create policy "profiles readable by authenticated" on public.profiles for select to authenticated using (true);
create policy "own profile insert" on public.profiles for insert to authenticated with check (id=auth.uid());
create policy "own profile update" on public.profiles for update to authenticated using (id=auth.uid()) with check (id=auth.uid());
create policy "members read chats" on public.chats for select to authenticated using (exists(select 1 from public.chat_members m where m.chat_id=id and m.user_id=auth.uid()));
create policy "signed user creates chat" on public.chats for insert to authenticated with check (created_by=auth.uid());
create policy "members read memberships" on public.chat_members for select to authenticated using (exists(select 1 from public.chat_members mine where mine.chat_id=chat_id and mine.user_id=auth.uid()));
create policy "chat creator adds members" on public.chat_members for insert to authenticated with check (user_id=auth.uid() or exists(select 1 from public.chats c where c.id=chat_id and c.created_by=auth.uid()));
create policy "members read messages" on public.messages for select to authenticated using (exists(select 1 from public.chat_members m where m.chat_id=messages.chat_id and m.user_id=auth.uid()));
create policy "members send own messages" on public.messages for insert to authenticated with check (sender_id=auth.uid() and exists(select 1 from public.chat_members m where m.chat_id=messages.chat_id and m.user_id=auth.uid()));
create policy "sender updates own messages" on public.messages for update to authenticated using (sender_id=auth.uid()) with check (sender_id=auth.uid());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name,phone) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','Пользователь'),new.phone) on conflict(id) do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
